#!/bin/sh
# name mangling 与 extern "C"：用 nm 实证符号名差异
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > str.cpp << 'EOF'
#include <cstdio>

namespace demo {
    int add(int a, int b) { return a + b; }
}

extern "C" int c_add(int a, int b)     /* 按 C 规则生成符号名：不做修饰 */
{
    return demo::add(a, b);
}

int overloaded(int x) { return x; }         /* C++ 重载，必然被修饰 */
double overloaded(double x) { return x; }

int main(void)
{
    printf("c_add(2, 3) = %d\n", c_add(2, 3));
    return 0;
}
EOF

g++ -c str.cpp -o str.o
nm str.o        # 注意 _ZN4demo3addEii、_Z10overloadedi/dd 等被修饰的名字
nm -C str.o     # -C 反修饰，显示人类可读签名
